 const r=await env.DB.prepare(`SELECT r.*,u.first_name,u.last_name,u.username,u.telegram_user_id FROM service_requests r LEFT JOIN users u ON u.id=r.user_id WHERE r.id=? AND r.client_deleted_at IS NULL`).bind(id).first<any>();
 if(!r){await safeEdit(env,msg,l3(locale,'⚠️ Заявку не знайдено.','⚠️ Nie znaleziono zlecenia.','⚠️ Request not found.'),backPanel(locale));return}
